import{_ as t,V as e,W as r,Z as l,a0 as o}from"./framework-c954d91f.js";const p="/assets/posts/ai-tech/1779175810145-83104f9c-79bf-4c6f-b5c4-8ccd8c991d1f.png",n="/assets/posts/ai-tech/1779175839314-a1994ad5-63dd-4a88-b3b3-653086048e3f.png",s={},a=o('<h1 id="大模型训练的-6倍法则" tabindex="-1"><a class="header-anchor" href="#大模型训练的-6倍法则" aria-hidden="true">#</a> 大模型训练的“6倍法则”</h1><p>很多人看大模型训练成本时，经常会看到一个公式：</p><blockquote><p><strong>训练 FLOPs ≈ 6 × 参数量 × Token 数</strong></p></blockquote><p>70B 模型、1T Token、几百张 GPU、训练几十天……这些数字背后，几乎都绕不开这条经验公式。</p><p>但很多人第一次看到时都会困惑：</p><ul><li>这个 <strong>6</strong> 到底从哪来？</li><li>它是在算 <strong>显存</strong>，还是在算 <strong>训练速度</strong>？</li><li>为什么不是 2，也不是 4？</li></ul><p>答案是：</p><blockquote><p>这条公式估算的是 <strong>训练总计算量</strong>，也就是训练过程中总共要做多少次浮点运算。</p></blockquote><h2 id="一、先搞清楚-flops-不是-gpu-速度" tabindex="-1"><a class="header-anchor" href="#一、先搞清楚-flops-不是-gpu-速度" aria-hidden="true">#</a> 一、先搞清楚：FLOPs 不是 GPU 速度</h2><h3 id="flops-是什么" tabindex="-1"><a class="header-anchor" href="#flops-是什么" aria-hidden="true">#</a> FLOPs 是什么？</h3><blockquote><p><strong>FLOPs = Floating Point Operations = 浮点运算次数</strong></p></blockquote><p>它描述的是：</p><blockquote><p><strong>一共要做多少计算。</strong></p></blockquote><p>你可以把它理解成“总工作量”。</p><p>比如：</p><ul><li>一次乘法，可以粗略记作 1 次 FLOP</li><li>一次加法，也可以粗略记作 1 次 FLOP</li></ul><p>所以，FLOPs 回答的是这个问题：</p><blockquote><p><strong>这个模型训练，总共要算多少次？</strong></p></blockquote><h3 id="flop-s-又是什么" tabindex="-1"><a class="header-anchor" href="#flop-s-又是什么" aria-hidden="true">#</a> FLOP/s 又是什么？</h3><blockquote><p><strong>FLOP/s = 每秒浮点运算次数</strong></p></blockquote><p>它描述的是：</p><blockquote><p><strong>硬件每秒能完成多少计算。</strong></p></blockquote><p>如果用一个更生活化的比喻：</p><table><thead><tr><th>概念</th><th>更容易理解的类比</th></tr></thead><tbody><tr><td>FLOPs</td><td>一共有多少砖要搬</td></tr><tr><td>FLOP/s</td><td>每秒能搬多少砖</td></tr></tbody></table><p>所以：</p><blockquote><p><strong>FLOPs 说的是工作量，FLOP/s 说的是速度。</strong></p></blockquote><p>训练时间大致可以写成：</p><blockquote><p><strong>训练时间 ≈ 总 FLOPs ÷ 实际 FLOP/s</strong></p></blockquote><p>也就是说，<code>6 × 参数量 × Token 数</code> 不是在说“跑得多快”，而是在说“活有多少”。</p>',29),i=o('<figure><img src="'+p+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="二、从一个最简单的-linear-层开始" tabindex="-1"><a class="header-anchor" href="#二、从一个最简单的-linear-层开始" aria-hidden="true">#</a> 二、从一个最简单的 Linear 层开始</h2><p>大模型里最耗算力的操作，本质上大多都是 <strong>矩阵乘法</strong>。</p><p>先看一个最简单的线性层：</p><blockquote><p><strong>y = x @ W</strong></p></blockquote><p>假设：</p><ul><li><code>x</code> 的 shape 是 <code>(B, D)</code></li><li><code>W</code> 的 shape 是 <code>(D, K)</code></li><li><code>y</code> 的 shape 是 <code>(B, K)</code></li></ul><p>这里可以这样理解：</p><ul><li><code>B</code>：Token 数</li><li><code>D</code>：输入维度</li><li><code>K</code>：输出维度</li><li><code>W</code>：模型参数</li></ul><p>于是，参数量就是：</p><blockquote><p><strong>参数量 = D × K</strong></p></blockquote><h2 id="三、为什么前向传播是-2-份" tabindex="-1"><a class="header-anchor" href="#三、为什么前向传播是-2-份" aria-hidden="true">#</a> 三、为什么前向传播是 2 份？</h2><p>前向传播只做一件大事：</p><blockquote><p><strong>算输出 y = x @ W</strong></p></blockquote><p>矩阵乘法里的每个输出元素，本质上都是一个点积。</p><p>也就是说，对于每个输出位置，都会发生：</p><ul><li>若干次乘法</li><li>若干次加法</li></ul><p>粗略估算时，我们通常把它近似写成：</p><blockquote><p><strong>一次乘法 + 一次加法 ≈ 2 FLOPs</strong></p></blockquote><p>因此，前向传播的计算量大约是：</p><blockquote><p><strong>forward FLOPs ≈ 2 × B × D × K</strong></p></blockquote><p>又因为：</p><ul><li><code>B = Token 数</code></li><li><code>D × K = 参数量</code></li></ul><p>所以可以写成：</p><blockquote><p><strong>forward FLOPs ≈ 2 × Token 数 × 参数量</strong></p></blockquote><p>这就是为什么大家常说：</p><blockquote><p><strong>前向传播占 2 份。</strong></p></blockquote><h2 id="四、为什么反向传播是-4-份" tabindex="-1"><a class="header-anchor" href="#四、为什么反向传播是-4-份" aria-hidden="true">#</a> 四、为什么反向传播是 4 份？</h2><p>训练和推理最大的区别在于：</p><ul><li><strong>推理只需要前向传播</strong></li><li><strong>训练还需要反向传播</strong></li></ul><p>而反向传播里，通常要额外计算两类梯度。</p><h3 id="_1-参数梯度" tabindex="-1"><a class="header-anchor" href="#_1-参数梯度" aria-hidden="true">#</a> 1）参数梯度</h3><p>第一件事，是计算参数的梯度：</p><blockquote><p><strong>W.grad = x.T @ y.grad</strong></p></blockquote><p>它的含义是：</p><blockquote><p><strong>loss 对参数 W 的梯度是多少？</strong></p></blockquote><p>这个矩阵乘法的计算量，和 forward 是同一个量级：</p><blockquote><p><strong>≈ 2 × Token 数 × 参数量</strong></p></blockquote><h3 id="_2-输入梯度" tabindex="-1"><a class="header-anchor" href="#_2-输入梯度" aria-hidden="true">#</a> 2）输入梯度</h3><p>第二件事，是把梯度继续传回上一层：</p><blockquote><p><strong>x.grad = y.grad @ W.T</strong></p></blockquote><p>它的含义是：</p><blockquote><p><strong>loss 对输入 x 的梯度是多少？</strong></p></blockquote><p>为什么这一步也必须算？</p><p>因为大模型不是只有一层 Linear，而是一层接一层。如果不把梯度继续往前传，前面的层就没法更新。</p><p>这一步的计算量同样大约是：</p><blockquote><p><strong>≈ 2 × Token 数 × 参数量</strong></p></blockquote><p>所以，反向传播总共是：</p><ul><li>参数梯度：2 份</li><li>输入梯度：2 份</li></ul><p>合起来就是：</p><blockquote><p><strong>backward FLOPs ≈ 4 × Token 数 × 参数量</strong></p></blockquote><p>也就是：</p><blockquote><p><strong>反向传播占 4 份。</strong></p></blockquote><h2 id="五、为什么最后会变成-6-倍" tabindex="-1"><a class="header-anchor" href="#五、为什么最后会变成-6-倍" aria-hidden="true">#</a> 五、为什么最后会变成 6 倍？</h2><p>把前向和反向加在一起：</p><table><thead><tr><th>阶段</th><th>近似计算量</th></tr></thead><tbody><tr><td>Forward</td><td>2 × Token 数 × 参数量</td></tr><tr><td>Backward</td><td>4 × Token 数 × 参数量</td></tr><tr><td>合计</td><td>6 × Token 数 × 参数量</td></tr></tbody></table><p>因此，训练总 FLOPs 通常可以近似写成：</p><blockquote><p><strong>训练 FLOPs ≈ 6 × 参数量 × Token 数</strong></p></blockquote><p>这个 <strong>6</strong> 不是玄学，也不是拍脑袋，而是从一个线性层的矩阵乘法 forward/backward 推出来的。</p><p>更直白一点：</p><blockquote><p><strong>forward 做 1 次大矩阵乘法，backward 做 2 次，所以总量约是 6 份。</strong></p></blockquote><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-hidden="true">#</a><!-- 这是一张图片，ocr 内容为： --></h2><figure><img src="'+n+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="六、一个具体例子-70b-模型到底有多贵" tabindex="-1"><a class="header-anchor" href="#六、一个具体例子-70b-模型到底有多贵" aria-hidden="true">#</a> 六、一个具体例子：70B 模型到底有多贵？</h2><p>假设一个模型有：</p><ul><li><strong>参数量 = 70B</strong></li><li><strong>训练数据 = 1T Tokens</strong></li></ul><p>那么训练计算量大约就是：</p><blockquote><p><strong>6 × 70B × 1T = 4.2 × 10^23 FLOPs</strong></p></blockquote><p>这意味着什么？</p><p>这不是一个“有点大”的数字，而是一个天文级数字。</p><p>也正因为如此，大模型训练才会：</p><ul><li>需要大量 GPU</li><li>训练时间很长</li><li>电力和机器成本都非常高</li></ul><p>换句话说：</p><blockquote><p>大模型训练不是简单“把数据喂一遍”，而是每个 Token 都要在巨大的参数矩阵上反复做乘加计算。</p></blockquote><h2 id="七、bf16-fp16-会改变这个-6-倍吗" tabindex="-1"><a class="header-anchor" href="#七、bf16-fp16-会改变这个-6-倍吗" aria-hidden="true">#</a> 七、BF16 / FP16 会改变这个 6 倍吗？</h2><p>很多人会继续问：</p><blockquote><p>如果我用了 BF16、FP16、Tensor Core，这个 6 倍会不会变小？</p></blockquote><p>一般来说：</p><blockquote><p><strong>不会。</strong></p></blockquote><p>原因很简单：</p><ul><li><code>6 × 参数量 × Token 数</code> 描述的是 <strong>总工作量</strong></li><li>BF16 / FP16 / Tensor Core 优化的是 <strong>完成这份工作量的速度</strong></li></ul><p>也就是说，低精度优化通常不会让“要干的活变少”，而是让 GPU：</p><ul><li>算得更快</li><li>吞吐更高</li><li>显存更省</li><li>成本更低</li></ul><p>所以你可以这样记：</p><blockquote><p><strong>6 倍公式：决定工作量</strong><br><strong>低精度优化：提升速度与效率</strong></p></blockquote><p>同样一堆砖，低精度不是让砖变少，而是让你搬得更快。</p><h2 id="八、这个公式是不是精确到每一个算子" tabindex="-1"><a class="header-anchor" href="#八、这个公式是不是精确到每一个算子" aria-hidden="true">#</a> 八、这个公式是不是精确到每一个算子？</h2><p>也不是。</p><p>它是一个非常有用的 <strong>经验估算公式</strong>，适合帮助我们快速判断训练成本的数量级。</p><p>真实训练里，除了矩阵乘法，还会有很多其他开销，比如：</p><ul><li>Attention score</li><li>Softmax</li><li>LayerNorm</li><li>激活函数</li><li>Dropout</li><li>Embedding</li><li>优化器更新</li><li>通信开销</li><li>显存读写</li></ul><p>但在大模型里，矩阵乘法通常占据主要计算量，所以：</p><blockquote><p><strong>训练 FLOPs ≈ 6 × 参数量 × Token 数</strong></p></blockquote><p>依然是一个非常实用的近似公式。</p><p>它特别适合用来理解这些问题：</p><ul><li>模型为什么越大越贵？</li><li>Token 为什么越多越贵？</li><li>训练为什么比推理贵很多？</li></ul><h2 id="九、最后总结" tabindex="-1"><a class="header-anchor" href="#九、最后总结" aria-hidden="true">#</a> 九、最后总结</h2><p>把整篇文章压缩成一句话：</p><blockquote><p><strong>大模型训练的“6倍法则”，本质上来自线性层矩阵乘法的 forward 和 backward。</strong></p></blockquote><p>你可以把它记成下面这张“账单”：</p><ul><li><strong>前向传播</strong>：算输出，占 2 份</li><li><strong>反向传播</strong>：算参数梯度，占 2 份</li><li><strong>反向传播</strong>：算输入梯度，占 2 份</li></ul><p>所以最终：</p><blockquote><p><strong>训练 FLOPs ≈ 6 × 参数量 × Token 数</strong></p></blockquote><p>理解了这个公式之后，你再去看大模型训练成本，就不会只停留在“参数很多”“GPU 很贵”这种模糊印象上。</p><p>你会更清楚地知道：</p><blockquote><p>每一个 Token，都要穿过巨大的参数矩阵；<br> 每一次训练，不仅要算答案，还要把误差反向传回去。<br> 这，就是大模型训练真正烧钱的地方。</p></blockquote>',106);function c(d,u){return e(),r("div",null,[a,l(" 这是一张图片，ocr 内容为： "),i])}const h=t(s,[["render",c],["__file","大模型训练的“6倍法则”.html.vue"]]);export{h as default};
